"use client";

import { useState, useRef } from "react";
import { cn } from "@/lib/utils";
import { Field, controlBase, controlClasses } from "./field";

function sanitizeMoney(raw: string, allowNegative: boolean, decimals: number): string {
  let s = raw.replace(allowNegative ? /[^0-9.-]/g : /[^0-9.]/g, "");
  if (allowNegative) {
    const negative = s.startsWith("-");
    s = s.replace(/-/g, "");
    if (negative) s = "-" + s;
  }
  const dot = s.indexOf(".");
  if (dot !== -1) s = s.slice(0, dot + 1) + s.slice(dot + 1).replace(/\./g, "");
  if (decimals === 0) s = s.split(".")[0];
  else if (dot !== -1) {
    const [i, f = ""] = s.split(".");
    s = i + "." + f.slice(0, decimals);
  }
  return s;
}

function moneyToNumber(s: string): number | null {
  if (s === "" || s === "-" || s === ".") return null;
  const n = Number(s);
  return Number.isFinite(n) ? n : null;
}

/**
 * Group the integer part of a sanitized numeric string with locale
 * thousand separators, preserving a trailing "." and any typed fraction
 * digits (including trailing zeros) exactly as entered.
 *
 * Examples (en-KE / en-US grouping):
 *   "1234"     -> "1,234"
 *   "1234."    -> "1,234."
 *   "1234.5"   -> "1,234.5"
 *   "-1234.50" -> "-1,234.50"
 */
function groupMoney(s: string, locale: string): string {
  if (s === "" || s === "-") return s;

  const negative = s.startsWith("-");
  const unsigned = negative ? s.slice(1) : s;

  const dot = unsigned.indexOf(".");
  const intPart = dot === -1 ? unsigned : unsigned.slice(0, dot);
  const hasDot = dot !== -1;
  const fracPart = hasDot ? unsigned.slice(dot + 1) : "";

  const groupedInt =
    intPart === ""
      ? ""
      : Number(intPart).toLocaleString(locale, { useGrouping: true, maximumFractionDigits: 0 });

  let out = groupedInt;
  if (hasDot) out += "." + fracPart;
  if (negative) out = "-" + out;
  return out;
}

/** Count digits in a string up to (not including) index `pos`. */
function digitsBefore(s: string, pos: number): number {
  let n = 0;
  for (let i = 0; i < pos && i < s.length; i++) {
    if (s[i] >= "0" && s[i] <= "9") n++;
  }
  return n;
}

/** Find the string index just after the `count`-th digit. */
function indexAfterDigits(s: string, count: number): number {
  if (count <= 0) {
    // Place caret before the first digit (after an optional leading "-").
    return s.startsWith("-") ? 1 : 0;
  }
  let seen = 0;
  for (let i = 0; i < s.length; i++) {
    if (s[i] >= "0" && s[i] <= "9") {
      seen++;
      if (seen === count) return i + 1;
    }
  }
  return s.length;
}

interface MoneyInputProps {
  id?: string;
  label?: string;
  hint?: string;
  error?: string;
  disabled?: boolean;
  readOnly?: boolean;
  placeholder?: string;
  currency?: string;
  value: number | null;
  onChange: (value: number | null) => void;
  decimals?: number;
  allowNegative?: boolean;
  max?: number;
  min?: number;
  locale?: string;
}

export function MoneyInput({
  id,
  label,
  hint,
  error,
  disabled,
  readOnly,
  placeholder = "0.00",
  currency,
  value,
  onChange,
  decimals = 2,
  allowNegative = false,
  max,
  min,
  locale = "en-KE",
}: MoneyInputProps) {
  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState("");
  const inputRef = useRef<HTMLInputElement>(null);

  const format = (n: number | null) =>
    n === null || Number.isNaN(n)
      ? ""
      : n.toLocaleString(locale, {
          minimumFractionDigits: decimals,
          maximumFractionDigits: decimals,
        });

  // While editing, show the grouped draft (thousand separators applied
  // live); otherwise show the fully formatted value.
  const display = editing ? groupMoney(draft, locale) : format(value);

  return (
    <Field label={label} hint={hint} error={error} htmlFor={id}>
      <div className="relative flex items-center">
        {currency && (
          <span className="pointer-events-none absolute left-3 text-sm text-text-tertiary">
            {currency}
          </span>
        )}
        <input
          ref={inputRef}
          id={id}
          inputMode="decimal"
          disabled={disabled}
          readOnly={readOnly}
          placeholder={placeholder}
          value={display}
          aria-invalid={Boolean(error) || undefined}
          onFocus={() => {
            setEditing(true);
            setDraft(value === null ? "" : String(value));
          }}
          onChange={(e) => {
            const el = e.target;
            const prevGrouped = el.value;
            const caret = el.selectionStart ?? prevGrouped.length;
            // Digits before the caret drive where the caret should land
            // after re-grouping (separators are ignored in the count).
            const digitsLeft = digitsBefore(prevGrouped, caret);

            const cleaned = sanitizeMoney(prevGrouped, allowNegative, decimals);
            setDraft(cleaned);
            onChange(moneyToNumber(cleaned));

            const grouped = groupMoney(cleaned, locale);
            const nextCaret = indexAfterDigits(grouped, digitsLeft);
            // Restore caret after React writes the grouped value.
            requestAnimationFrame(() => {
              const node = inputRef.current;
              if (node) node.setSelectionRange(nextCaret, nextCaret);
            });
          }}
          onBlur={() => {
            setEditing(false);
            let n = moneyToNumber(draft);
            if (n !== null) {
              if (typeof max === "number") n = Math.min(n, max);
              if (typeof min === "number") n = Math.max(n, min);
            }
            onChange(n);
          }}
          className={cn(
            controlBase,
            controlClasses(error, disabled, readOnly),
            "h-10 tabular-nums text-right pr-3",
            currency ? "pl-12" : "pl-3"
          )}
        />
      </div>
    </Field>
  );
}

"use client";

import { cn } from "@/lib/utils";

interface FieldCounter {
  text: string;
  warn?: boolean;
}

interface FieldProps {
  label?: string;
  hint?: string;
  error?: string;
  required?: boolean;
  htmlFor?: string;
  counter?: FieldCounter;
  /** id applied to the hint/error message, for aria-describedby wiring. */
  messageId?: string;
  children: React.ReactNode;
}

/**
 * Field — the shared wrapper for every form control.
 * Provides label, hint/error message slot, and optional counter.
 * Error replaces hint to prevent layout shift.
 *
 * Per Mathesis "Text Input" guideline: label is always visible above the
 * field (never placeholder-as-label), errors show inline below, and the
 * message is linked to the control via `messageId` + aria-describedby.
 */
export function Field({
  label,
  hint,
  error,
  required,
  htmlFor,
  counter,
  messageId,
  children,
}: FieldProps) {
  const message = error || hint;
  return (
    <div className="flex w-full flex-col gap-1.5">
      {label && (
        <label
          htmlFor={htmlFor}
          className="flex items-center gap-1 text-[13px] font-medium text-text"
        >
          {label}
          {required && (
            <span className="text-error" aria-hidden>
              *
            </span>
          )}
        </label>
      )}
      {children}
      <div className="flex items-start justify-between gap-3">
        <p
          id={messageId}
          className={cn("text-xs leading-snug", error ? "text-error" : "text-text-secondary")}
        >
          {message || "\u00A0"}
        </p>
        {counter && (
          <span
            className={cn(
              "shrink-0 text-xs tabular-nums",
              counter.warn ? "text-error" : "text-text-tertiary"
            )}
          >
            {counter.text}
          </span>
        )}
      </div>
    </div>
  );
}

/**
 * Shared base classes for form controls that sit inside Field.
 * Per guideline: 40px height (h-10), 8px radius (rounded-lg), 1px border.
 */
export const controlBase = cn(
  "w-full rounded-lg border text-sm bg-surface text-text transition-colors",
  "placeholder:text-text-tertiary",
  "focus:outline-none focus-visible:border-accent focus-visible:ring-2 focus-visible:ring-accent/25",
  "disabled:cursor-not-allowed disabled:bg-bg-secondary disabled:opacity-60",
  "read-only:bg-bg-secondary"
);

/**
 * State classes for a control: border/color per error & disabled state.
 * Returns Tailwind classes (token-backed) — no inline styles.
 */
export function controlClasses(error?: string, disabled?: boolean, readOnly?: boolean) {
  return cn(
    error ? "border-error focus-visible:ring-error/25 focus-visible:border-error" : "border-border",
    readOnly && "read-only:bg-bg-secondary",
    disabled && "text-text-tertiary"
  );
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

/**
 * Merge class names with clsx semantics + Tailwind conflict resolution.
 * Prefer this in all components.
 */
export function cn(...inputs: ClassValue[]): string {
  return twMerge(clsx(inputs));
}

/**
 * Concatenate class names, filtering out falsy values.
 * @deprecated Prefer {@link cn} — it also resolves Tailwind class conflicts.
 */
export function cx(...args: (string | false | null | undefined)[]): string {
  return args.filter(Boolean).join(" ");
}

/**
 * Focus ring style helper.
 * @deprecated Focus rings are now handled globally via the
 * `:focus-visible` rule in `globals.css` and the `focus-visible:*`
 * utilities. This remains only for backwards compatibility.
 */
export function ring(color: string = "var(--color-accent)") {
  return { outlineColor: color };
}
